{"command": "str_replace", "new_str": "impl<'a, C: Catalog> Planner<'a, C> {
    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Self { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::Begin { .. } => Ok(Plan::Select(Node::Nothing { columns: vec![] })),
            ast::Statement::Commit => Ok(Plan::Select(Node::Nothing { columns: vec![] })),
            ast::Statement::Rollback => Ok(Plan::Select(Node::Nothing { columns: vec![] })),
            ast::Statement::Explain(stmt) => {
                let plan = self.build(*stmt)?;
                Ok(plan)
            }
            ast::Statement::CreateTable { name, columns } => {
                self.build_create_table(name, columns)
            }
            ast::Statement::DropTable { name, if_exists } => {
                self.build_drop_table(name, if_exists)
            }
            ast::Statement::Delete { table, r#where } => {
                self.build_delete(table, r#where)
            }
            ast::Statement::Insert { table, columns, values } => {
                self.build_insert(table, columns, values)
            }
            ast::Statement::Update { table, set, r#where } => {
                self.build_update(table, set, r#where)
            }
            ast::Statement::Select {
                select,
                from,
                r#where,
                group_by,
                having,
                order_by,
                offset,
                limit,
            } => {
                self.build_select(select, from, r#where, group_by, having, order_by, offset, limit)
            }
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut schema_columns = Vec::new();
        for col in columns {
            schema_columns.push(Column {
                name: col.name,
                datatype: col.datatype,
                primary_key: col.primary_key,
                nullable: col.nullable,
                default: col.default.map(|e| Self::build_expression(e, &Scope::new())).transpose()?,
                unique: col.unique,
                index: col.index,
                references: col.references,
            });
        }
        let table = Table { name, columns: schema_columns };
        Ok(Plan::CreateTable { schema: table })
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        let table_ref = self.catalog.get_table(&table).ok_or_else(|| errinput!("unknown table: {}", table))?;
        let mut scope = Scope::new();
        scope.add_table(table_ref, None)?;
        let condition = r#where.map(|e| Self::build_expression(e, &scope)).transpose()?;
        let source = Node::Filter {
            source: Box::new(Node::Scan {
                table: table_ref.clone(),
                filter: condition,
                alias: None,
            }),
            predicate: condition.unwrap_or(Expression::Literal(Value::Boolean(true))),
        };
        let primary_key = table_ref.columns.iter().position(|c| c.primary_key).unwrap_or(0);
        Ok(Plan::Delete { table, primary_key, source })
    }

    /// Builds an INSERT plan.
    fn build_insert(
        &self,
        table: String,
        columns: Option<Vec<String>>,
        values: Vec<Vec<ast::Expression>>,
    ) -> Result<Plan> {
        let table_ref = self.catalog.get_table(&table).ok_or_else(|| errinput!("unknown table: {}", table))?;
        let column_names = columns.unwrap_or_else(|| table_ref.columns.iter().map(|c| c.name.clone()).collect());
        let mut scope = Scope::new();
        scope.add_table(table_ref, None)?;
        let mut row_values = Vec::new();
        for row in values {
            let mut values = Vec::new();
            for expr in row {
                values.push(Self::build_expression(expr, &scope)?);
            }
            row_values.push(values);
        }
        let source = Node::Values { rows: row_values };
        let column_map = if column_names.len() == table_ref.columns.len() {
            None
        } else {
            let mut map = HashMap::new();
            for (i, col_name) in column_names.iter().enumerate() {
                if let Some(col_idx) = table_ref.columns.iter().position(|c| &c.name == col_name) {
                    map.insert(col_idx, i);
                }
            }
            Some(map)
        };
        Ok(Plan::Insert { table: table_ref.clone(), column_map, source })
    }

    /// Builds an UPDATE plan.
    fn build_update(
        &self,
        table: String,
        set: BTreeMap<String, Option<ast::Expression>>,
        r#where: Option<ast::Expression>,
    ) -> Result<Plan> {
        let table_ref = self.catalog.get_table(&table).ok_or_else(|| errinput!("unknown table: {}", table))?;
        let mut scope = Scope::new();
        scope.add_table(table_ref, None)?;
        let assignments: Vec<(usize, Expression)> = set
            .into_iter()
            .map(|(col, expr)| {
                let col_idx = table_ref.columns.iter().position(|c| c.name == col).ok_or_else(|| errinput!("unknown column: {}", col))?;
                let expr = expr.map(|e| Self::build_expression(e, &scope)).transpose()?;
                Ok((col_idx, expr.unwrap_or(Expression::Literal(Value::Null))))
            })
            .collect::<Result<_>>()?;
        let condition = r#where.map(|e| Self::build_expression(e, &scope)).transpose()?;
        let source = Node::Filter {
            source: Box::new(Node::Scan {
                table: table_ref.clone(),
                filter: condition,
                alias: None,
            }),
            predicate: condition.unwrap_or(Expression::Literal(Value::Boolean(true))),
        };
        let primary_key = table_ref.columns.iter().position(|c| c.primary_key).unwrap_or(0);
        Ok(Plan::Update { table: table_ref.clone(), primary_key, source, expressions: assignments })
    }

    /// Builds a SELECT plan.
    #[allow(clippy::too_many_arguments)]
    fn build_select(
        &self,
        select: Vec<(ast::Expression, Option<String>)>,
        from: Vec<ast::From>,
        r#where: Option<ast::Expression>,
        group_by: Vec<ast::Expression>,
        having: Option<ast::Expression>,
        order_by: Vec<(ast::Expression, ast::Direction)>,
        offset: Option<ast::Expression>,
        limit: Option<ast::Expression>,
    ) -> Result<Plan> {
        let mut scope = Scope::new();
        let from_node = self.build_from_clause(from, &mut scope)?;

        // WHERE clause
        let where_node = if let Some(expr) = r#where {
            let condition = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(from_node),
                predicate: condition,
            }
        } else {
            from_node
        };

        // GROUP BY and aggregates
        let aggregates = Self::collect_aggregates(&select, &having, &order_by);
        let group_by_scope = scope.spawn();

        let aggregate_node = if !group_by.is_empty() || !aggregates.is_empty() {
            let mut group_by_expressions = Vec::new();
            for expr in group_by {
                group_by_expressions.push(Self::build_expression(expr, &group_by_scope)?);
            }
            let mut aggregate_expressions = Vec::new();
            for expr in aggregates {
                if let ast::Expression::Operator(ast::Operator::Function(name, args)) = &expr {
                    let args: Vec<Expression> = args
                        .iter()
                        .map(|e| Self::build_expression(e.clone(), &group_by_scope))
                        .collect::<Result<_>>()?;
                    let agg = match name.to_lowercase().as_str() {
                        "count" => Aggregate::Count(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null))),
                        "sum" => Aggregate::Sum(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null))),
                        "avg" => Aggregate::Average(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null))),
                        "min" => Aggregate::Min(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null))),
                        "max" => Aggregate::Max(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null))),
                        _ => Aggregate::Count(Expression::Literal(Value::Null)),
                    };
                    aggregate_expressions.push(agg);
                }
            }
            Node::Aggregate {
                source: Box::new(where_node),
                group_by: group_by_expressions,
                aggregates: aggregate_expressions,
            }
        } else {
            where_node
        };

        // HAVING clause
        let having_node = if let Some(expr) = having {
            let condition = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(aggregate_node),
                predicate: condition,
            }
        } else {
            aggregate_node
        };

        // ORDER BY
        let order_by_node = if !order_by.is_empty() {
            let mut order_by_expressions = Vec::new();
            for (expr, direction) in order_by {
                order_by_expressions.push((Self::build_expression(expr, &scope)?, direction.into()));
            }
            Node::Order {
                source: Box::new(having_node),
                key: order_by_expressions,
            }
        } else {
            having_node
        };

        // OFFSET and LIMIT
        let offset_node = if let Some(expr) = offset {
            let offset = Self::build_constant_value(expr)?;
            let offset = match offset {
                Value::Integer(i) => i as usize,
                _ => return Err(errinput!("OFFSET must be an integer")),
            };
            Node::Offset {
                source: Box::new(order_by_node),
                offset,
            }
        } else {
            order_by_node
        };

        let limit_node = if let Some(expr) = limit {
            let limit = Self::build_constant_value(expr)?;
            let limit = match limit {
                Value::Integer(i) => i as usize,
                _ => return Err(errinput!("LIMIT must be an integer")),
            };
            Node::Limit {
                source: Box::new(offset_node),
                limit,
            }
        } else {
            offset_node
        };

        // SELECT projection
        let mut expressions = Vec::new();
        let mut aliases = Vec::new();
        for (expr, alias) in select {
            expressions.push(Self::build_expression(expr, &scope)?);
            aliases.push(alias.as_ref().map(Label::Unqualified).unwrap_or(Label::None));
        }
        let project_node = Node::Projection {
            source: Box::new(limit_node),
            expressions,
            aliases,
        };

        Ok(Plan::Select(project_node))
    }

    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        if from.is_empty() {
            return Ok(Node::Nothing { columns: vec![] });
        }

        let mut result = self.build_from(from[0].clone(), scope)?;

        for item in from.iter().skip(1) {
            let child_scope = scope.spawn();
            let child = self.build_from(item.clone(), &mut child_scope.clone())?;
            result = Node::NestedLoopJoin {
                left: Box::new(result),
                right: Box::new(child),
                predicate: None,
                outer: false,
            };
            scope.merge(child_scope)?;
        }

        Ok(result)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let table = self.catalog.get_table(&name).ok_or_else(|| errinput!("unknown table: {}", name))?;
                parent_scope.add_table(&table, alias.as_deref())?;
                Ok(Node::Scan {
                    table,
                    filter: None,
                    alias,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let mut left_scope = parent_scope.spawn();
                let left_node = self.build_from(*left, &mut left_scope)?;

                let mut right_scope = left_scope.spawn();
                let right_node = self.build_from(*right, &mut right_scope)?;

                parent_scope.merge(left_scope)?;
                parent_scope.merge(right_scope)?;

                let condition = predicate.map(|e| Self::build_expression(e, parent_scope)).transpose()?;

                let outer = r#type.is_outer();
                Ok(Node::NestedLoopJoin {
                    left: Box::new(left_node),
                    right: Box::new(right_node),
                    predicate: condition,
                    outer,
                })
            }
        }
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        if let ast::Expression::Operator(ast::Operator::Function(name, args)) = expr {
            let args: Vec<Expression> = args
                .into_iter()
                .map(|e| Self::build_expression(e, scope))
                .collect::<Result<_>>()?;

            match name.to_lowercase().as_str() {
                "count" => Ok(Aggregate::Count(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null)))),
                "sum" => Ok(Aggregate::Sum(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null)))),
                "avg" => Ok(Aggregate::Average(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null)))),
                "min" => Ok(Aggregate::Min(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null)))),
                "max" => Ok(Aggregate::Max(args.into_iter().next().unwrap_or(Expression::Literal(Value::Null)))),
                _ => Err(errinput!("unknown aggregate function: {}", name)),
            }
        } else {
            Err(errinput!("expected aggregate function"))
        }
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        if let ast::Expression::Operator(ast::Operator::Function(name, _)) = expr {
            let name_lower = name.to_lowercase();
            name_lower == "count" || name_lower == "sum" || name_lower == "avg" || name_lower == "min" || name_lower == "max"
        } else {
            false
        }
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();
        for (expr, _) in select {
            if Self::is_aggregate_function(expr) {
                aggregates.push(expr.clone());
            }
        }
        if let Some(expr) = having {
            if Self::is_aggregate_function(expr) {
                aggregates.push(expr.clone());
            }
        }
        for (expr, _) in order_by {
            if Self::is_aggregate_function(expr) {
                aggregates.push(expr.clone());
            }
        }
        aggregates
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        match expr {
            ast::Expression::All => Err(errinput!("cannot use * in expression")),
            ast::Expression::Column(table, name) => {
                let idx = scope.lookup_column(table.as_deref(), &name)?;
                Ok(Expression::Column(idx))
            }
            ast::Expression::Literal(lit) => {
                Ok(Expression::Literal(match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                }))
            }
            ast::Expression::Function(name, args) => {
                let args: Vec<Expression> = args
                    .into_iter()
                    .map(|e| Self::build_expression(e, scope))
                    .collect::<Result<_>>()?;
                Ok(Expression::Function(name, args))
            }
            ast::Expression::Operator(op) => {
                Self::build_operator(op, scope)
            }
        }
    }

    /// Builds an operator expression.
    fn build_operator(op: ast::Operator, scope: &Scope) -> Result<Expression> {
        use ast::Operator::*;
        match op {
            And(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::And, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Not(e) => {
                let e = Self::build_expression(*e, scope)?;
                Ok(Expression::UnaryNot(Box::new(e)))
            }
            Or(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Or, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Equal(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Equal, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            GreaterThan(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::GreaterThan, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            GreaterThanOrEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::GreaterThanOrEqual, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Is(lhs, lit) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let value = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Float(f) if f.is_nan() => Value::Float(f),
                    _ => return Err(errinput!("invalid IS literal")),
                };
                Ok(Expression::Is(Box::new(lhs), value))
            }
            LessThan(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::LessThan, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            LessThanOrEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::LessThanOrEqual, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            NotEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::NotEqual, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Add(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Add, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Subtract(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Subtract, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Multiply(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Multiply, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Divide(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Divide, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Remainder(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Remainder, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Exponentiate(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Exponentiate, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
            Factorial(e) => {
                let e = Self::build_expression(*e, scope)?;
                Ok(Expression::Factorial(Box::new(e)))
            }
            Identity(e) => {
                let e = Self::build_expression(*e, scope)?;
                Ok(Expression::Identity(Box::new(e)))
            }
            Negate(e) => {
                let e = Self::build_expression(*e, scope)?;
                Ok(Expression::Negate(Box::new(e)))
            }
            Like(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::BinaryOp { op: crate::sql::types::BinaryOperator::Like, lhs: Box::new(lhs), rhs: Box::new(rhs) })
            }
        }
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<Value> {
        match expr {
            ast::Expression::Literal(lit) => Ok(match lit {
                ast::Literal::Null => Value::Null,
                ast::Literal::Boolean(b) => Value::Boolean(b),
                ast::Literal::Integer(i) => Value::Integer(i),
                ast::Literal::Float(f) => Value::Float(f),
                ast::Literal::String(s) => Value::String(s),
            }),
            _ => Err(errinput!("expected constant expression")),
        }
    }
}
